        "        6:(35,65),\n",
        "        7:(65,65),\n",
        "        8:(85,60),\n",
        "\n",
        "        9:(15,30),\n",
        "        10:(35,35),\n",
        "        11:(65,35),\n",
        "        12:(85,30),\n",
        "\n",
        "        13:(20,10),\n",
        "        14:(40,5),\n",
        "        15:(70,5),\n",
        "        16:(90,10)\n",
        "    }\n",
        "\n",
        "    plt.figure(figsize=(12,8))\n",
        "\n",
        "    colors = [\"red\",\"blue\",\"green\",\"orange\"]\n",
        "\n",
        "    for vehicle_id in range(data[\"num_vehicles\"]):\n",
        "\n",
        "        index = routing.Start(vehicle_id)\n",
        "\n",
        "        route_edges = []\n",
        "\n",
        "        while not routing.IsEnd(index):\n",
        "\n",
        "            next_index = solution.Value(\n",
        "                routing.NextVar(index)\n",
        "            )\n",
        "\n",
        "            from_node = manager.IndexToNode(index)\n",
        "            to_node = manager.IndexToNode(next_index)\n",
        "\n",
        "            route_edges.append((from_node,to_node))\n",
        "\n",
        "            index = next_index\n",
        "\n",
        "        G = nx.DiGraph()\n",
        "        G.add_edges_from(route_edges)\n",
        "\n",
        "        nx.draw_networkx_edges(\n",
        "            G,\n",
        "            pos,\n",
        "            edge_color=colors[vehicle_id],\n",
        "            width=3,\n",
        "            arrows=True,\n",
        "            arrowsize=20\n",
        "        )\n",
        "\n",
        "    nx.draw_networkx_nodes(\n",
        "        nx.Graph(),\n",
        "        pos,\n",
        "        nodelist=[0],\n",
        "        node_size=1800\n",
        "    )\n",
        "\n",
        "    nx.draw_networkx_nodes(\n",
        "        nx.Graph(),\n",
        "        pos,\n",
        "        nodelist=range(1,17),\n",
        "        node_size=1000\n",
        "    )\n",
        "\n",
        "    labels = {0:\"Depot\"}\n",
        "\n",
        "    for i in range(1,17):\n",
        "        labels[i] = f\"C{i}\"\n",
        "\n",
        "    nx.draw_networkx_labels(\n",
        "        nx.Graph(),\n",
        "        pos,\n",
        "        labels,\n",
        "        font_size=9\n",
        "    )\n",
        "\n",
        "    plt.title(\"Vehicle Routing Problem\")\n",
        "    plt.axis(\"off\")\n",
        "    plt.show()\n",
        "\n",
        "\n",
        "def main():\n",
        "\n",
        "    data = create_data_model()\n",
        "\n",
        "    manager = pywrapcp.RoutingIndexManager(\n",
        "        len(data[\"distance_matrix\"]),\n",
        "        data[\"num_vehicles\"],\n",
        "        data[\"depot\"]\n",
        "    )\n",
        "\n",
        "    routing = pywrapcp.RoutingModel(manager)\n",
        "\n",
        "    def distance_callback(from_index, to_index):\n",
        "\n",
        "        from_node = manager.IndexToNode(from_index)\n",
        "        to_node = manager.IndexToNode(to_index)\n",
        "\n",
        "        return data[\"distance_matrix\"][from_node][to_node]\n",
        "\n",
        "    transit_callback_index = routing.RegisterTransitCallback(\n",
        "        distance_callback\n",
        "    )\n",
        "\n",
        "    routing.SetArcCostEvaluatorOfAllVehicles(\n",
        "        transit_callback_index\n",
        "    )\n",
        "\n",
        "    # Ép chia tuyến nhiều xe hơn\n",
        "    routing.AddDimension(\n",
        "        transit_callback_index,\n",
        "        0,\n",
        "        100,\n",
        "        True,\n",
        "        \"Distance\"\n",
        "    )\n",
        "\n",
        "    distance_dimension = routing.GetDimensionOrDie(\n",
        "        \"Distance\"\n",
        "    )\n",
        "\n",
        "    distance_dimension.SetGlobalSpanCostCoefficient(\n",
        "        100\n",
        "    )\n",
        "\n",
        "    search_parameters = pywrapcp.DefaultRoutingSearchParameters()\n",
        "\n",
        "    search_parameters.first_solution_strategy = (\n",
        "        routing_enums_pb2.FirstSolutionStrategy.PATH_CHEAPEST_ARC\n",
        "    )\n",
        "\n",
        "    search_parameters.local_search_metaheuristic = (\n",
        "        routing_enums_pb2.LocalSearchMetaheuristic.GUIDED_LOCAL_SEARCH\n",
        "    )\n",
        "\n",
        "    search_parameters.time_limit.seconds = 5\n",
        "\n",
        "    solution = routing.SolveWithParameters(\n",
        "        search_parameters\n",
        "    )\n",
        "\n",
        "    if solution:\n",
        "\n",
        "        print_solution(\n",
        "            data,\n",
        "            manager,\n",
        "            routing,\n",
        "            solution\n",
        "        )\n",
        "\n",
        "        plot_routes(\n",
        "            data,\n",
        "            manager,\n",
        "            routing,\n",
        "            solution\n",
        "        )\n",
        "\n",
        "    else:\n",
        "        print(\"No solution found\")\n",
        "\n",
        "\n",
        "main()"
